#!/usr/bin/env bash
# land_e3dc_variant_wave.sh - the compose-rotation commit-at-out variant wave
# (the sixteenth-return window's near-copy queue item; the census x7
# size=0x10C byte-identical wave, pre-checked by scripts/e3dcv_check.py:
# seven asm rows, one per target except mainmenu_jp, byte-identical, the
# delta vs the landed compose-rotation anchor exactly the six
# commit-destination words $4->$6 - the per-row src units are generated by
# scripts/gen_e3dc_variant_srcs.py and must exist before this runs).
# Per target: one-line yaml flip [off, asm, NAME] -> [off, c,   NAME]
# (row name == unit name, the memclr law), delete the row's .s listing
# (slps may use the flat asm/nonmatchings path), make verify. ANY verify
# failure reverts that target's edits (unverified bytes never land).
# slps runs LAST (the gp-window first-shot risk, tenth-return class).
# Run from the repo root, witness 8/8.
set -u

declare -A ROWS=(
  [g3_eu]="0x29820, func_80049020"
  [g3_jp]="0x29E08, func_80049608"
  [g3org_eu]="0x26C74, func_80046474"
  [g3org_jp]="0x272A4, func_80046AA4"
  [sces_00269]="0x14400, func_80033C00"
  [mainmenu_eu]="0x3DCFC, func_8005D4FC"
  [slps_00270]="0x14938, func_80034138"
)

TARGETS="${*:-g3_eu g3_jp g3org_eu g3org_jp sces_00269 mainmenu_eu slps_00270}"
FAILED=""
for t in $TARGETS; do
  echo "=== $t: flipping 1 row to its own c unit"
  git checkout -- "config/splat.$t.yaml" 2>/dev/null
  row="${ROWS[$t]}"
  off="${row%%, *}"
  name="${row##*, }"
  line=$(grep -n "^\s*- \[${off}, asm, ${name}\]" "config/splat.$t.yaml" | head -1 | cut -d: -f1)
  if [ -z "$line" ]; then
    echo "  RECIPE MISS: - [${off}, asm, ${name}] not found in splat.$t.yaml"
    FAILED="$FAILED $t(recipe)"; continue
  fi
  sed -i "${line}s/- \[${off}, asm, ${name}\]/- [${off}, c,   ${name}]/" "config/splat.$t.yaml"
  if ! grep -q "^\s*- \[${off}, c,   ${name}\]" "config/splat.$t.yaml"; then
    echo "  FLIP MISS: sed did not produce the c row"; git checkout -- "config/splat.$t.yaml"
    FAILED="$FAILED $t(flip)"; continue
  fi
  sfile="asm/$t/nonmatchings/${name}.s"
  [ -f "$sfile" ] || sfile="asm/nonmatchings/${name}.s"
  if [ -f "$sfile" ]; then rm "$sfile"; echo "  flipped ${off} ${name} -> c (+ removed ${sfile})"; else
    echo "  flipped ${off} ${name} -> c (.s not present - clean_stale_asm will sweep)"; fi
  if make verify TARGET="$t" >/tmp/verify_ev_$t.log 2>&1; then
    echo "  VERIFY GREEN: $t"
  else
    echo "  VERIFY FAILED: $t - reverting (tail below)"
    tail -8 /tmp/verify_ev_$t.log
    git checkout -- "config/splat.$t.yaml"
    git checkout -- "asm/$t/nonmatchings/" 2>/dev/null
    git checkout -- "asm/nonmatchings/" 2>/dev/null
    FAILED="$FAILED $t(verify)"
  fi
done
echo "=== wave result: FAILED=[$FAILED] (empty = all green)"
[ -z "$FAILED" ]
